import{_ as a,a as t,b as r,c as o,d as i}from"./chunks/qr_libre2direct_samsung_30.BlQvG7BZ.js";import{_ as n,o as s,c as l,a3 as u}from"./chunks/framework.g9mfNVRQ.js";const g=JSON.parse('{"title":"Libre 2 Direct","description":"","frontmatter":{"source_hash":"09c4f80004","source_commit":"7a18e7c"},"headers":[],"relativePath":"fr/troubleshoot/libre2direct.md","filePath":"fr/troubleshoot/libre2direct.md"}'),c={name:"fr/troubleshoot/libre2direct.md"};function d(h,e,p,m,b,v){return s(),l("div",null,[...e[0]||(e[0]=[u('<h1 id="libre2-direct" tabindex="-1">Libre2 Direct <a class="header-anchor" href="#libre2-direct" aria-label="Permalink to &quot;Libre2 Direct {#libre2-direct}&quot;">​</a></h1><p>Le Libre2 (UE uniquement) peut se connecter directement à xDrip sans transmetteur. Cette page décrit à quoi doit ressembler un système qui fonctionne.</p><p>Voir ici pour <a href="./../install/libre2.html#prerequisites">apprendre à le configurer...</a></p><h2 id="what-it-should-look-like" tabindex="-1">Ce que vous devez voir <a class="header-anchor" href="#what-it-should-look-like" aria-label="Permalink to &quot;Ce que vous devez voir {#what-it-should-look-like}&quot;">​</a></h2><p>Une fois la configuration correcte et un nouveau capteur en marche, les pages d&#39;état et les journaux de xDrip doivent ressembler à ce qui est montré ci-dessous. Remarque : rien ne change dans l&#39;onglet Uploaders pour le fonctionnement en Libre 2 direct.</p><p>Allez dans l&#39;État du système de xDrip, puis dans BT Device. Si vous ne savez pas comment faire, consultez d&#39;abord <a href="./systemstatus.html">cette page</a>.</p><h2 id="classic-status-page" tabindex="-1">Page d&#39;état classique <a class="header-anchor" href="#classic-status-page" aria-label="Permalink to &quot;Page d&#39;état classique {#classic-status-page}&quot;">​</a></h2><img src="'+a+'" style="zoom:40%;"><h3 id="version" tabindex="-1">Version <a class="header-anchor" href="#version" aria-label="Permalink to &quot;Version {#version}&quot;">​</a></h3><p>Dépend de votre version de xDrip</p><h3 id="data-source" tabindex="-1">Source de données <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Source de données {#data-source}&quot;">​</a></h3><p>Doit afficher LimiTTer. Même si c&#39;est trompeur, c&#39;est le comportement normal.</p><h3 id="bluetooth-device" tabindex="-1">Bluetooth Device <a class="header-anchor" href="#bluetooth-device" aria-label="Permalink to &quot;Bluetooth Device {#bluetooth-device}&quot;">​</a></h3><p>C&#39;est l&#39;identifiant de série unique du capteur. Il commence par ABBOTT...</p><h3 id="connection-status" tabindex="-1">Connection Status <a class="header-anchor" href="#connection-status" aria-label="Permalink to &quot;Connection Status {#connection-status}&quot;">​</a></h3><p>Doit indiquer « connected ».</p><h3 id="sensor-start" tabindex="-1">Sensor Start <a class="header-anchor" href="#sensor-start" aria-label="Permalink to &quot;Sensor Start {#sensor-start}&quot;">​</a></h3><p>L&#39;heure de démarrage du capteur.</p><h3 id="restart-collector-button" tabindex="-1">Bouton Redémarrer le collecteur <a class="header-anchor" href="#restart-collector-button" aria-label="Permalink to &quot;Bouton Redémarrer le collecteur {#restart-collector-button}&quot;">​</a></h3><p>Arrête la fonction de collecte de xDrip puis la relance de zéro (y compris la connexion Bluetooth à l&#39;appareil qui avait été arrêtée)</p><h3 id="forget-device-button" tabindex="-1">Bouton Oublier ce périphérique <a class="header-anchor" href="#forget-device-button" aria-label="Permalink to &quot;Bouton Oublier ce périphérique {#forget-device-button}&quot;">​</a></h3><p>Retire l&#39;appareil Bluetooth des appareils connus : vous devez faire un scan Bluetooth pour le retrouver et l&#39;appairer, ou refaire un scan NFC.</p><h3 id="refresh-button" tabindex="-1">Bouton Rafraîchir <a class="header-anchor" href="#refresh-button" aria-label="Permalink to &quot;Bouton Rafraîchir {#refresh-button}&quot;">​</a></h3><p>L&#39;état n&#39;est pas en temps réel, contrairement à l&#39;onglet BT Device ; Rafraîchir vérifie l&#39;état de la connexion. <br></p><h2 id="bt-device-page" tabindex="-1">Page BT Device <a class="header-anchor" href="#bt-device-page" aria-label="Permalink to &quot;Page BT Device {#bt-device-page}&quot;">​</a></h2><p>Faites glisser l&#39;écran vers la gauche pour afficher la page BT Device.</p><img src="'+t+'" style="zoom:40%;"><h3 id="bluetooth-collector-status" tabindex="-1">Bluetooth Collector Status <a class="header-anchor" href="#bluetooth-collector-status" aria-label="Permalink to &quot;Bluetooth Collector Status {#bluetooth-collector-status}&quot;">​</a></h3><h3 id="phone-service-state" tabindex="-1">Phone Service State <a class="header-anchor" href="#phone-service-state" aria-label="Permalink to &quot;Phone Service State {#phone-service-state}&quot;">​</a></h3><p>Indique normalement l&#39;heure de la dernière connexion. Il affiche parfois XXX Blu Con XXX, mais c&#39;est une phase temporaire qui laissera place à Last Connect HH:MM</p><h3 id="bluetooth-device-1" tabindex="-1">Bluetooth Device <a class="header-anchor" href="#bluetooth-device-1" aria-label="Permalink to &quot;Bluetooth Device {#bluetooth-device-1}&quot;">​</a></h3><p>Le Bluetooth doit toujours être connecté.</p><h3 id="device-mac-address" tabindex="-1">Device Mac Address <a class="header-anchor" href="#device-mac-address" aria-label="Permalink to &quot;Device Mac Address {#device-mac-address}&quot;">​</a></h3><p>Doit être une suite de six paires de chiffres hexadécimaux. Unique pour chaque capteur.</p><h3 id="bluetooth-pairing" tabindex="-1">Bluetooth Pairing <a class="header-anchor" href="#bluetooth-pairing" aria-label="Permalink to &quot;Bluetooth Pairing {#bluetooth-pairing}&quot;">​</a></h3><p>Doit rester sur « Disabled, tap to enable ». Faites attention à NE PAS appuyer dessus.<br> Si vous appuyez dessus par erreur, appuyez à nouveau jusqu&#39;à ce qu&#39;il revienne à désactivé.</p><h3 id="slowest-wake-up" tabindex="-1">Slowest wake up <a class="header-anchor" href="#slowest-wake-up" aria-label="Permalink to &quot;Slowest wake up {#slowest-wake-up}&quot;">​</a></h3><p>Vous pouvez l&#39;ignorer. xDrip ne passe pas son temps à attendre les valeurs : il commence à les attendre après un certain délai (traditionnellement 5 minutes). Si aucune donnée n&#39;arrive à ce moment-là, vous verrez « Woke up early », ce qui signifie que xDrip s&#39;attendait à ce que des données soient prêtes mais qu&#39;il n&#39;y en a pas. Slowest wake up est le plus long délai rencontré avant de recevoir normalement des données.</p><h3 id="next-wake-up" tabindex="-1">Next Wake up <a class="header-anchor" href="#next-wake-up" aria-label="Permalink to &quot;Next Wake up {#next-wake-up}&quot;">​</a></h3><p>Doit indiquer 5 minutes</p><br><h1 id="event-logs" tabindex="-1">Journal des événements <a class="header-anchor" href="#event-logs" aria-label="Permalink to &quot;Journal des événements {#event-logs}&quot;">​</a></h1><p>Dans le menu vertical ... en haut à droite de l&#39;écran principal, sélectionnez Afficher le journal d&#39;événements</p><img src="'+r+'" style="zoom:40%;"><h3 id="libreoopalgorithm" tabindex="-1">LibreOOPAlgorithm <a class="header-anchor" href="#libreoopalgorithm" aria-label="Permalink to &quot;LibreOOPAlgorithm {#libreoopalgorithm}&quot;">​</a></h3><p>Vous devez voir une série de commentaires de la forme HH:MM Creating BG time = NNN raw = RRRR où HH:MM est l&#39;heure, NNN un compteur de temps interne (une nouvelle valeur a un nombre supérieur à la précédente) et RRRR la valeur brute lue sur le capteur, en dixièmes de mg/dl (1000 correspond à 100 mg/dl, soit 5,5 mmol/l). Cela montre que le capteur est connecté et que de bonnes valeurs sont relevées. Une valeur doit arriver chaque minute, même si certaines peuvent manquer, comme c&#39;est le cas ici.</p><br><h2 id="cannot-nfc-scan-new-sensor-nfc-timeout" tabindex="-1">Impossible de scanner un nouveau capteur en NFC - délai NFC dépassé <a class="header-anchor" href="#cannot-nfc-scan-new-sensor-nfc-timeout" aria-label="Permalink to &quot;Impossible de scanner un nouveau capteur en NFC - délai NFC dépassé {#cannot-nfc-scan-new-sensor-nfc-timeout}&quot;">​</a></h2><p>Un problème apparaît, surtout en Europe : impossible de démarrer le capteur par un scan NFC. Au lieu du message « Scan OK ! » après « Scan en cours », vous verrez « Délai de lecture NFC » ou « Délai de diagnostic NFC ». Regardez dans les journaux de débogage. Si vous voyez le message « Sensor type unknown, returning libre1 as failsafe » ou « Libre sensor of type Libre1 detected », vous devez mettre à jour OOP2 et xDrip.</p><img src="'+o+'" style="zoom:40%;"><p>Vous devrez télécharger une version d&#39;OOP2 de fin mai 2023 ou plus récente, et mettre à jour xDrip-plus vers la version 2023-05-27 ou ultérieure. Une nouvelle version des capteurs, « C5 », au firmware mis à jour, nécessite ces versions à jour.</p><h2 id="losing-bluetooth-connection-with-samsung-phone" tabindex="-1">Pertes de connexion Bluetooth avec un téléphone Samsung ? <a class="header-anchor" href="#losing-bluetooth-connection-with-samsung-phone" aria-label="Permalink to &quot;Pertes de connexion Bluetooth avec un téléphone Samsung ? {#losing-bluetooth-connection-with-samsung-phone}&quot;">​</a></h2><p>Plusieurs utilisateurs de téléphones Samsung signalent qu&#39;ils perdent parfois la connexion avec le capteur. Si c&#39;est votre cas, vous pouvez essayer de modifier certains paramètres Bluetooth. Cliquez sur le QR code puis scannez-le comme indiqué.</p><p><a href="./libre2direct-qr-samsung.html"><img src="'+i+'" style="zoom:50%;"></a></p><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2023.05.26" target="_blank" rel="noreferrer"><em>Dernière modification le 4/6/2023</em></a></p>',55)])])}const x=n(c,[["render",d]]);export{g as __pageData,x as default};
